var particles = [];
var nums;
var particleDensity = 4000; // desity of the brush smaller-> more nums of brushes
var noiseScale = 800;//curve
var maxLife = 1; // the length of each particle from its start to the end
var	simulationSpeed = 0.1; // speed of the brush
var fadeFrame = 0; 
var backgroundColor;
var visualMode = 0;
var numModes = 4;
var invertColors = false;

function setup(){
	nums = windowWidth * windowHeight / particleDensity;
	backgroundColor = color(20, 20, 20);
	createCanvas(windowWidth, windowHeight);
	background(backgroundColor);
	for(var i = 0; i < nums; i++){
		particles[i] = new Particle();
	}
}

function draw(){
	noStroke();

	++fadeFrame; //fadeFramme == 1
	if(fadeFrame % 5 == 0){ 
		if(invertColors){ //boolean 
			blendMode(ADD); //call blendMode function - > ADD (SUM OF A AND B)
		} else {
			blendMode(DIFFERENCE); //call blendMode function - > DIFFERENCE (MIX)
		}
		fill(1, 1, 1);
		rect(0,0,width,height);// A

		if(invertColors){
			blendMode(DARKEST);
		} else {
			blendMode(LIGHTEST);
		}
		fill(backgroundColor);
		rect(0,0,width,height);//B
	}

	blendMode(BLEND); //bg
	smooth();
	for(var i = 0; i < nums; i++){
		var iterations = map(i,0,nums,16, 10); //the range of the dots (larger -> dots may be seperated)
		var radius = map(i,0,nums, 2, 3); //the radian of each dot

		particles[i].move(iterations);//call move function ? 
		particles[i].checkEdge();//?

		var alpha = 255;
		var particleColor;
		var fadeRatio;
		fadeRatio = min(particles[i].life  / maxLife, 1); //life ranged from 0 to 1
		fadeRatio = min((maxLife - particles[i].life) / maxLife, fadeRatio);
		var colorCase = visualMode;
		if(visualMode == 0)
		{
			colorCase = int(particles[i].pos.x / width * 3) + 1; //case of colors
		}
		switch(colorCase)
		{
			case 1:
			/*	var lifeRatioGrayscale = min(255, (255 * particles[i].life / maxLife) + red(backgroundColor));
			  particleColor = color(lifeRatioGrayscale, alpha * fadeRatio);*/
				particleColor = color(red(particles[i].color) - 50, blue(particles[i].color)-50 , green(particles[i].color) + 10);
				break;
			case 2:
				particleColor = particles[i].color;
				break;
			case 3:
				particleColor = color(blue(particles[i].color) + 70, green(particles[i].color) + 20, red(particles[i].color) - 50);
				break;
		}
		if(invertColors){
			particleColor = color(255 - red(particleColor), 255 - green(particleColor), 255 - blue(particleColor));
		}
		fill(red(particleColor), green(particleColor), blue(particleColor), alpha * fadeRatio);
		particles[i].display(radius);//draw ellispe
	} 
}

function Particle(){
// member properties and initialization
	this.vel = createVector(0, 0);
	this.pos = createVector(random(0, width), random(0, height));
	this.life = random(0, maxLife);
	this.flip = int(random(0,2)) * 2 - 1;//the movement
	var randColor = int(random(0,3));
	switch(randColor)
	{
		case 0:
			this.color = color(110,57,204); 
			break;
		case 1:
			this.color = color(7,153,242); 
			break;
		case 2:
			this.color = color(255,255,255);
			break;

	}

// member functions
	this.move = function(iterations){ //var iterations = map(i,0,nums,10, 1);
		//iterations = 16; //trial: it will change the speed, life and shape
		if((this.life -= 0.01666) < 0)
			this.respawn();
		while(iterations > 0){
			var angle = noise(this.pos.x/noiseScale, this.pos.y/noiseScale)*TWO_PI*noiseScale*this.flip; //TWO_PI => tidy circle */noiseScale => big number/large enough curve
			this.vel.x = cos(angle);
			this.vel.y = sin(angle);
			this.vel.mult(simulationSpeed);
			this.pos.add(this.vel);
			--iterations;
		}
	}

	this.checkEdge = function(){
		if(this.pos.x > width || this.pos.x < 0 || this.pos.y > height || this.pos.y < 0){
			this.respawn();
		}
	}

	this.respawn = function(){ //re draw
		this.pos.x = random(0, width);
		this.pos.y = random(0, height);
		this.life = maxLife;
	}

	this.display = function(r){
		ellipse(this.pos.x, this.pos.y, r, r);
	}
}
//stop here 3/29
function advanceVisual()
{
	visualMode = ++visualMode % numModes;
	if(visualMode == 0){
		invertColors = !invertColors;
		backgroundColor = invertColors ? color(235, 235, 235) : color(20, 20, 20);
	}
	noiseSeed(random()*Number.MAX_SAFE_INTEGER);
	background(backgroundColor);
	for(var i = 0; i < nums; i++){
		particles[i].respawn();
		particles[i].life = random(0,maxLife);
  }
}

function keyPressed()
{
	advanceVisual();
}

function touchStarted()
{
	advanceVisual();
}

